#!/bin/sh
# Installs the "Disks & RAID" and "Shut down" pages (luci-app-diskprep) on every first boot.
cat > /tmp/diskprep.b64 <<'EOF'

EOF
ucode -e 'import * as fs from "fs"; fs.writefile("/tmp/diskprep.tgz", b64dec(trim(fs.readfile("/tmp/diskprep.b64"))));' && tar xzf /tmp/diskprep.tgz -C / && /etc/init.d/stora-power enable
rm -f /tmp/diskprep.b64 /tmp/diskprep.tgz /tmp/luci-indexcache*
rm -rf /tmp/luci-modulecache
exit 0
